{
    "sql": "WITH FemaleClientAccounts AS (SELECT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON a.district_id = d.district_id WHERE c.gender = 'F' AND dp.type = 'OWNER'), OldestFemale AS (SELECT * FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), LowestAvgSalary AS (SELECT * FROM OldestFemale WHERE avg_salary = (SELECT MIN(avg_salary) FROM OldestFemale)), HighestAvgSalary AS (SELECT MAX(avg_salary) AS max_avg_salary FROM FemaleClientAccounts) SELECT l.account_id, l.avg_salary AS lowest_avg_salary, h.max_avg_salary AS highest_avg_salary, (h.max_avg_salary - l.avg_salary) AS salary_gap FROM LowestAvgSalary l CROSS JOIN HighestAvgSalary h"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F' AND dp.type = 'OWNER'), OldestFemale AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), LowestAvgSalary AS (SELECT account_id FROM FemaleClientAccounts WHERE avg_salary = (SELECT MIN(avg_salary) FROM FemaleClientAccounts)), TargetAccounts AS (SELECT DISTINCT account_id FROM OldestFemale INTERSECT SELECT DISTINCT account_id FROM LowestAvgSalary), SalaryStats AS (SELECT MIN(avg_salary) AS min_salary, MAX(avg_salary) AS max_salary FROM FemaleClientAccounts) SELECT t.account_id, (s.max_salary - s.min_salary) AS salary_gap FROM TargetAccounts t CROSS JOIN SalaryStats s"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F'), OldestFemale AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), LowestAvgSalary AS (SELECT account_id FROM FemaleClientAccounts WHERE avg_salary = (SELECT MIN(avg_salary) FROM FemaleClientAccounts)), TargetAccounts AS (SELECT account_id FROM OldestFemale INTERSECT SELECT account_id FROM LowestAvgSalary) SELECT a.account_id, (SELECT MAX(d.A11) FROM district d) - (SELECT MIN(d.A11) FROM district d) AS salary_gap FROM TargetAccounts t JOIN account a ON t.account_id = a.account_id"
}

