{
    "sql": "WITH FemaleClientAccounts AS (SELECT c.client_id, c.birth_date, a.account_id, d.A11 AS avg_salary FROM client c JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE c.gender = 'F'), OldestFemale AS (SELECT account_id, avg_salary FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), LowestAvgSalary AS (SELECT account_id, avg_salary FROM FemaleClientAccounts WHERE avg_salary = (SELECT MIN(avg_salary) FROM FemaleClientAccounts)), HighestAvgSalary AS (SELECT MAX(avg_salary) AS max_salary FROM FemaleClientAccounts) SELECT DISTINCT o.account_id, (h.max_salary - l.avg_salary) AS salary_gap FROM OldestFemale o JOIN LowestAvgSalary l ON o.account_id = l.account_id CROSS JOIN HighestAvgSalary h"
